def replay(kind):
 pin,index=kind.split('/'); original=root/pin/index/'execution'; rebuilt=root/(pin+'-'+index+'-independent-location-replay')
 command=proof.checked_location_compile(original,rebuilt,pin,programs)
 a=proof.compiled_pin_units(original);b=proof.compiled_pin_units(rebuilt)
